import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"在线完成第一次检索","description":"","frontmatter":{},"headers":[],"relativePath":"zh/get-started/online.md","filePath":"zh/get-started/online.md","lastUpdated":1793111003000}'),n={name:"zh/get-started/online.md"};function i(l,e,s,h,p,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="在线完成第一次检索" tabindex="-1">在线完成第一次检索 <a class="header-anchor" href="#在线完成第一次检索" aria-label="Permalink to &quot;在线完成第一次检索&quot;">​</a></h1><p>在 <a href="https://paperseek.app/" target="_blank" rel="noreferrer">paperseek.app</a> 上把一个问题变成阅读清单，无需安装。大约五分钟。</p><p>更想用自己的设备？<a href="./local">安装社区版</a>。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><ul><li>一个用于注册账户的邮箱。公测期间每个账户每天获得 <strong>20 免费积分</strong>，一次检索消耗 <strong>1 积分</strong>。详见<a href="./../online/credits">服务与积分</a>。</li><li>没有账户？可以不登录做一次临时检索，见<a href="./../online/privacy#不登录检索">不登录检索</a>。临时检索不会保存。</li></ul><h2 id="_1-登录" tabindex="-1">1. 登录 <a class="header-anchor" href="#_1-登录" aria-label="Permalink to &quot;1. 登录&quot;">​</a></h2><p>打开 <a href="https://paperseek.app/" target="_blank" rel="noreferrer">paperseek.app</a>，点击侧栏底部的 <strong>未登录</strong>，选择 <strong>登录或注册</strong>。输入邮箱，确认验证码，设置密码。详细信息和其他登录方式见<a href="./../online/account">账户与登录</a>。</p><h2 id="_2-输入问题" tabindex="-1">2. 输入问题 <a class="header-anchor" href="#_2-输入问题" aria-label="Permalink to &quot;2. 输入问题&quot;">​</a></h2><p>登录后默认使用 <strong>PaperSeek 服务</strong>：模型由 PaperSeek 提供，任务消耗每日积分。</p><p>打开侧栏的<strong>文献检索</strong>。保留默认数据源 <strong>OpenAlex</strong>，预算保持 <strong>Auto</strong>，输入你的问题，例如：</p><blockquote><p>开源软件如何获得支持长期维护的资金？</p></blockquote><p>点击<strong>开始检索</strong>，或按 <strong>Ctrl+Enter / ⌘+Enter</strong>。表单会显示本次任务消耗的积分和今日剩余积分。</p><h2 id="_3-查看检索进展" tabindex="-1">3. 查看检索进展 <a class="header-anchor" href="#_3-查看检索进展" aria-label="Permalink to &quot;3. 查看检索进展&quot;">​</a></h2><p>PaperSeek 分四个可见阶段工作：理解问题、迭代适合数据源的检索式、召回并排序候选，最后呈现结果。运行中可以随时在页首停止。各阶段和数量的含义见<a href="./../guide/search">检索文献</a>。</p><h2 id="_4-阅读结果" tabindex="-1">4. 阅读结果 <a class="header-anchor" href="#_4-阅读结果" aria-label="Permalink to &quot;4. 阅读结果&quot;">​</a></h2><p>运行结束后打开<strong>检索结果</strong>。每篇文献显示摘要、带文字理由的相关性评分和原始记录链接。可将清单导出为 CSV、JSON、BibTeX 或 RIS。</p><p>这次运行会保存到你的账户，可从侧栏的<strong>检索历史</strong>重新打开。从这里还可以打开<a href="./../guide/citation-map">引用图谱</a>、运行<a href="./../guide/bibliometrics">文献计量分析</a>，或开始一篇<a href="./../guide/reviews">实验性综述</a>。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><a href="./../guide/search">检索文献</a>：预算、领域筛选、停止与重连。</li><li><a href="./../online/byok">自带密钥</a>：使用自己的模型和数据源密钥，不消耗积分。</li><li><a href="./../online/credits">服务与积分</a>：消耗、退回和每日恢复。</li></ul>',19)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
